INSERT INTO sales (`invoice_no`,`user_id`,`branch_id`,`discount_id`,`total_amount`,`discount_amount`,`final_total`,`payment_method`,`reference_no`,`amount_paid`,`change_amount`,`status`,`notes`,`sale_date`,`created_at`,`updated_at`,`receipt_metadata`) SELECT e.`invoice_no`,e.`user_id`,e.`branch_id`,e.`discount_id`,e.`total_amount`,e.`discount_amount`,e.`final_total`,e.`payment_method`,e.`reference_no`,e.`amount_paid`,e.`change_amount`,e.`status`,e.`notes`,e.`sale_date`,e.`created_at`,e.`updated_at`,e.`receipt_metadata` FROM phx_m30_sales e WHERE @phx_m30_insert ORDER BY e.sale_date,e.branch_id,e.invoice_no;
INSERT INTO sale_items (sale_id,`product_id`,`product_name_snapshot`,`cost_price_at_sale`,`quantity`,`price`,`subtotal`,`discount_applied`,`profit`,`created_at`,`stock_delivery_id`,`expiration_date_at_sale`,`generic_name_snapshot`,`strength_snapshot`,`tax_treatment_snapshot`,`vat_exemption_amount`,`statutory_discount_kind`) SELECT s.id,i.`product_id`,i.`product_name_snapshot`,i.`cost_price_at_sale`,i.`quantity`,i.`price`,i.`subtotal`,i.`discount_applied`,i.`profit`,i.`created_at`,i.`stock_delivery_id`,i.`expiration_date_at_sale`,i.`generic_name_snapshot`,i.`strength_snapshot`,i.`tax_treatment_snapshot`,i.`vat_exemption_amount`,i.`statutory_discount_kind` FROM phx_m30_items i JOIN sales s ON BINARY s.invoice_no=BINARY i.invoice_no AND s.notes=@phx_m30_note WHERE @phx_m30_insert ORDER BY i.created_at,i.product_id;
INSERT INTO stock_logs (`product_id`,`branch_id`,`user_id`,`action_type`,`quantity`,`previous_stock`,`new_stock`,`remarks`,`created_at`,`supplier_id`,`manufacturer`) SELECT e.`product_id`,e.`branch_id`,e.`user_id`,e.`action_type`,e.`quantity`,e.`previous_stock`,e.`new_stock`,e.`remarks`,e.`created_at`,e.`supplier_id`,e.`manufacturer` FROM phx_m30_logs e WHERE @phx_m30_insert ORDER BY e.created_at,e.branch_id,e.product_id;
